-- TEST71 final costing output authority cleanup.
create or replace function public.rr_upm_product_cost_actual_v722(p_canonical_lot_id text,p_data_mode text default 'TEST') returns jsonb language plpgsql stable security definer set search_path to 'public' as $function$
declare c jsonb:=public.rr_upm_product_cost_actual_v709(p_canonical_lot_id,p_data_mode);rows jsonb;begin select coalesce(jsonb_agg(case when x->>'component'='GATTA_PANNI' then x||jsonb_build_object('impact',false,'state','RETIRED_COMBINED','replacement','V701_RAW_BOM_AGGREGATE','cost_per_pc',0) else x end),'[]') into rows from jsonb_array_elements(coalesce(c->'materials_resolved','[]')) x;return c||jsonb_build_object('version','V722_CANONICAL_OUTPUT_CLEAN','materials_resolved',rows,'lineage_rule','LEGACY GATTA_PANNI MAY REMAIN AS AUDIT LINEAGE ONLY; NEVER IMPACT/COST AUTHORITY');end $function$;
create or replace function public.rr_upm_product_cost_actual_v723(p_canonical_lot_id text,p_data_mode text default 'TEST') returns jsonb language plpgsql stable security definer set search_path to 'public' as $function$
declare c jsonb:=public.rr_upm_product_cost_actual_v722(p_canonical_lot_id,p_data_mode);rows jsonb;print_app boolean:=coalesce((c->'printing'->>'applicable')::boolean,false);begin select coalesce(jsonb_agg(case when x->>'component'='PRINT_CHEMICAL' and not print_app then x||jsonb_build_object('impact',false,'state','NOT_APPLICABLE','cost_per_pc',0,'reason','PRINTING_NOT_APPLICABLE') else x end),'[]') into rows from jsonb_array_elements(coalesce(c->'materials_resolved','[]')) x;return c||jsonb_build_object('version','V723_APPLICABILITY_CLEAN_OUTPUT','materials_resolved',rows,'applicability_rule','LEGACY MATERIAL LINEAGE CANNOT CLAIM IMPACT WHEN ITS DEPARTMENT IS NOT APPLICABLE');end $function$;
create or replace function public.rr_upm_final_costing_v691(p_canonical_lot_id text,p_data_mode text default 'TEST') returns jsonb language plpgsql stable security definer set search_path to 'public' as $function$ declare full_ctx jsonb:=public.rr_upm_product_cost_actual_v723(p_canonical_lot_id,p_data_mode);scope jsonb:=public.rr_costing_user_scope_v760(null);private_ok boolean;role text;begin private_ok:=coalesce((scope->>'can_view_private_cost')::boolean,false);role:=upper(coalesce(scope->>'effective_role','WORKER'));if private_ok then return full_ctx||jsonb_build_object('security','SUPER_ADMIN_PRIVATE','canonical_authority','V723');end if;return jsonb_build_object('ok',full_ctx->'ok','version','V723_APPLICABILITY_CLEAN_OUTPUT','canonical_lot_id',p_canonical_lot_id,'lot_no',full_ctx->'lot_no','final_sale_rate',full_ctx->'final_sale_rate','costing_complete',full_ctx->'costing_complete','missing',full_ctx->'missing','security','PRIVATE_COST_OMITTED','effective_role',role);end $function$;